709	void test_verify_success() {
710	    TempArea tmp("verify_ok");
711	    const auto empty = bytes_of("");
712	    const auto a = bytes_of("a");
713	    const auto abc = bytes_of("abc");
714	    const auto hello = bytes_of("hello\n");
715	    const fs::path f_empty = tmp.root / "empty.bin";
716	    const fs::path f_a = tmp.root / "a.bin";
717	    const fs::path f_abc = tmp.root / "abc.bin";
718	    const fs::path f_hello = tmp.root / "hello.bin";
719	    write_file(f_empty, empty);
720	    write_file(f_a, a);
721	    write_file(f_abc, abc);
722	    write_file(f_hello, hello);
723	
724	    // 单文件：位置 0、空兄弟列表；内容叶子必须是带 0x00 前缀的叶子。
725	    {
726	        const MerkleVerifyResult v = verify_real({f_a}, 0, leaf_bytes(a));
727	        check(v.ok(), "verify single file: passes with the 0x00-prefixed leaf");
728	        check(v.valid && v.error.empty(),
729	              "verify success: valid is true and error is empty");
730	    }
731	    // 单个空文件：叶子 SHA-256(0x00)，与空批次根不同，仍正常通过。
732	    {
733	        const MerkleVerifyResult v =
734	            verify_real({f_empty}, 0, leaf_bytes(empty));
735	        check(v.ok(), "verify single empty file: passes with SHA-256(0x00)");
736	        check(branchaudit::merkle_verify_proof(
737	                  branchaudit::merkle_proof_file({f_empty}, 0).proof,
738	                  branchaudit::merkle_empty_root(), leaf_bytes(empty)).ok() ==
739	                      false,
740	              "verify: single empty-file proof fails against the empty batch "
741	              "root");
742	    }
743	
744	    // 两文件：两个位置互为镜像兄弟，各自通过。
745	    {
746	        check(verify_real({f_a, f_abc}, 0, leaf_bytes(a)).ok(),
747	              "verify two files: index 0 passes");
748	        check(verify_real({f_a, f_abc}, 1, leaf_bytes(abc)).ok(),
749	              "verify two files: index 1 passes");
750	    }
751	
752	    // 三文件（奇数末节点提升，末位置缺第一层兄弟记录）必须正常通过。
753	    {
754	        const std::vector<fs::path> batch{f_a, f_abc, f_empty};
755	        check(verify_real(batch, 2, leaf_bytes(empty)).ok(),
756	              "verify 3 files index 2: proof with a promoted level omitted "
757	              "passes without padding records");
758	        check(verify_real(batch, 0, leaf_bytes(a)).ok(),
759	              "verify 3 files index 0: passes");
760	    }
