766	        const std::vector<std::vector<unsigned char>> five_data{
767	            a, abc, empty, hello, a};
768	        for (std::uint64_t i = 0; i < 5; ++i) {
769	            check(verify_real(batch, i, leaf_bytes(five_data[i])).ok(),
770	                  "verify 5-file index " + std::to_string(i) + " passes");
771	        }
772	    }
773	    {
774	        const std::array<std::vector<unsigned char>, 7> data = {
775	            empty, a, bytes_of("bb"), bytes_of("ccc"), bytes_of("dddd"),
